//go:build ignore

// Verify that the public skill matches the bootstrap generated by this CLI.
package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/doomerlabs/doomer/internal/managed"
)

func main() {
	skill := flag.String("skill", "", "public SKILL.md to verify")
	flag.Parse()
	if *skill == "" {
		fail("--skill is required")
	}
	actual, err := os.ReadFile(*skill)
	if err != nil {
		fail("read public skill: %v", err)
	}
	if err := managed.VerifyPublishedBootstrap(actual); err != nil {
		fail("%v", err)
	}
	fmt.Printf("Public skill matches CLI bootstrap %s (%s)\n", managed.BootstrapVersion, managed.BootstrapCLIRange)
}

func fail(format string, args ...any) {
	fmt.Fprintf(os.Stderr, format+"\n", args...)
	os.Exit(1)
}
